input.command:
python3 - <<'EOF'
import re, json, os
tmp = os.environ.get("TMPDIR","/tmp") + "/i008"
blocks = json.load(open(tmp + "/kstrto_blocks.json"))
bad = []
for b in blocks:
    m = re.match(r'^\s*(?:const\s+)?(?:int|long)?\s*(\w+)\s*=\s*kstrto', b[0][2])
    var = m.group(1) if m else "ret"
    tail = b[1:]
    checked = False
    for p,l,t in tail:
        # any check of var
        if re.search(r'\b%s\b' % var, t):
            if re.search(r'\bif\s*\(', t) or re.search(r'return\s+%s\b' % var, t) or re.search(r'\bgoto\b', t) or re.search(r'\?\s*%s\b' % var, t) or re.search(r'%s\s*=' % var, t):
                checked = True
                break
        if re.search(r'\bif\s*\([^)]*\b%s\b' % var, t):
            checked = True; break
    if not checked:
        bad.append(b)
print("blocks with no visible check in +8 lines:", len(bad))
for b in bad:
    print("----", b[0][0], b[0][1])
    for p,l,t in b:
        print(f"  {l}: {t}")
EOF

